package com.aicharacter.v3;
/** Quadruped gait is mechanically coupled; player intent never moves four independent legs. */
public final class CatWholeBodyMotorEngine{private CatWholeBodyMotorEngine(){}
 public static void advance(WorldState s,double dt){if(s==null||dt<=0)return;if(s.catRig==null)s.catRig=new CatRigState();CatRigState r=s.catRig;PhysicsBodyState p=s.catPhysics;double speed=s.catTravel!=null&&s.catTravel.active?s.catTravel.lastSpeed:0,gait=Math.max(0,Math.min(1,speed/105.0));double total=s.catTravel==null?0:Math.max(0,s.catTravel.distanceTravelled);if(total+1e-6<r.lastDistanceSample)r.lastDistanceSample=0;double travelled=Math.max(0,total-r.lastDistanceSample);r.lastDistanceSample=total;double stridePx=WorldUnits.mToPx(.42);r.gaitPhase=(r.gaitPhase+travelled/Math.max(1,stridePx))%1;double w=Math.sin(r.gaitPhase*Math.PI*2),q=Math.sin((r.gaitPhase+.5)*Math.PI*2);if(gait<.06){r.frontLeftContact=r.frontRightContact=r.hindLeftContact=r.hindRightContact=1;}else{r.frontLeftContact=w>=-.1?1:0;r.hindRightContact=r.frontLeftContact;r.frontRightContact=q>=-.1?1:0;r.hindLeftContact=r.frontRightContact;}r.frontLoad=Math.max(.28,Math.min(.72,.52-w*.10*gait));r.hindLoad=1-r.frontLoad;r.spineFlex=w*.08*gait;r.trunkLean=(1-(p==null?1:p.balance))*.10;if(p!=null){double contacts=r.frontLeftContact+r.frontRightContact+r.hindLeftContact+r.hindRightContact;double half=contacts>=3?.28:contacts>=2?.20:.11;p.supportLeft=-half;p.supportRight=half;p.centerOfMassX=r.trunkLean*.18+w*.045*gait;}}
}